+                    break;
+                case HDR:
+                    resolution = isInteger(methodParameter, sourceText, methodParameterOrdinal);
+                    break;
+                default:
+                    throw new QlIllegalArgumentException("Not handled PercentilesMethod [" + percentilesMethod + "]");
+            }
