+        }
+        Quantiles quantiles = result.getQuantiles();
+        if (quantiles != null) {
+            logUnexpectedResult(Quantiles.TYPE.getPreferredName());
+        }
+        FlushAcknowledgement flushAcknowledgement = result.getFlushAcknowledgement();
