+
+    /**
+     * If failed then there was an error parsing the results that cannot be recovered from
+     *
+     * @return true if failed
+     */
+    public boolean isFailed() {
+        return failed;
+    }
+
+    private boolean isAlive() {
+        if (processKilled) {
+            return false;
+        }
+        return process.isProcessAliveAfterWaiting();
+    }
