+        return numAnomalyJobsInQueue == that.numAnomalyJobsInQueue &&
+            numAnalyticsJobsInQueue == that.numAnalyticsJobsInQueue &&
+            Objects.equals(downScaleDelay, that.downScaleDelay);
+    }
+
+    @Override
