+                long lonLat = (((long) encodedLon) << 32) | encodedLat & 0xffffffffL;
+
+                values.set(index, lonLat);
+                empty.markNotMissing(index);
+            };
+        }
+
+        @Override
+        public void close() {
+            Releasables.close(values, empty);
+        }
+    }
+}

